import gurobipy as gp
from gurobipy import GRB
I = []
revenue = {}
demand = {}
inventory = {}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    i = vals['Product Name']
    I.append(i)
    try:
        revenue[i] = float(vals['Revenue'])
        demand[i] = int(vals['Demand'])
        inventory[i] = int(vals['Initial Inventory'])
    except Exception as e:
        raise ValueError(f'Invalid data for {i}: {e}')
if not set(revenue) == set(I) == set(demand) == set(inventory):
    raise ValueError('Missing data for some pizza types.')
m = gp.Model('Pizza_Fulfillment')
x = m.addVars(I, lb=0, vtype=GRB.INTEGER, name='')
for i in I:
    ub = min(demand[i], inventory[i])
    x[i].setAttr(GRB.Attr.UB, ub)
m.setObjective(gp.quicksum((revenue[i] * x[i] for i in I)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')